const fs = require('fs');
const orig = fs.readFileSync('/trajectory.txt', 'utf8').replace(/\r\n/g, '\n');
const trans = fs.readFileSync('/output/translation.md', 'utf8').replace(/\r\n/g, '\n');

const origTurns = orig.split(/(<\|user\|>|<\|assistant\|>)/).filter(Boolean);
const transTurns = trans.split(/(<\|user\|>|<\|assistant\|>)/).filter(Boolean);

for (let t = 0; t < origTurns.length; t += 2) {
  const oLines = origTurns[t+1].split('\n');
  const tLines = transTurns[t+1].split('\n');
  console.log('Turn', t/2 + 1, 'lines:', oLines.length, 'vs', tLines.length);
  if (oLines.length !== tLines.length) {
    console.log('MISMATCH IN TURN', t/2 + 1);
  }
}
"

